def _trozos_codigo(texto):
    trozos = []
    for linea in texto.splitlines():
        limpia = linea.strip()
        if not limpia:
            continue
        if limpia.endswith(":"):
            trozos.append(limpia)
            continue
        if "=" in limpia:
            trozos.append(limpia)
            continue
        if "(" in limpia or ")" in limpia:
            trozos.append(limpia)
            continue
        primera = limpia.split()[0]
        if primera in ("if", "def", "for", "return", "with", "import"):
            trozos.append(limpia)
    return trozos
